import type { Quat, Vec3 } from '../contracts/math';

/** Общий lifecycle любого препятствия курса. */
export interface ObstacleInstance {
  readonly id: string;
  /** Продвинуть состояние препятствия на deltaSeconds. */
  update(deltaSeconds: number): void;
  /** Освободить физические и графические ресурсы. */
  dispose(): void;
}

/** Физическая сторона препятствия: кинематическое тело, ведомое состоянием. */
export interface ObstacleBodyAdapter {
  setTransform(position: Vec3, rotation: Quat): void;
  setEnabled?(enabled: boolean): void;
  dispose(): void;
}

/** Визуальная сторона препятствия: меш, ведомый тем же состоянием. */
export interface ObstacleViewAdapter {
  setTransform(position: Vec3, rotation: Quat): void;
  dispose(): void;
}
