import type { Quat, Vec3 } from '../contracts/math';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { ObstacleBodyAdapter, ObstacleInstance, ObstacleViewAdapter } from './ObstacleInstance';

export type DoorPhase = 'closed' | 'opening' | 'open' | 'closing';
export type DoorMotion = 'slide' | 'swing';
export type DoorHinge = 'left' | 'right';

/** Автоматический цикл: сколько секунд дверь стоит в каждом крайнем положении. */
export interface DoorAutoCycle {
  openHoldSeconds: number;
  closedHoldSeconds: number;
  startOpen?: boolean;
}

export interface DoorConfig {
  id: string;
  /** Центр закрытой створки в мировых координатах. */
  position: Vec3;
  /** Габариты створки: x — ширина, y — высота, z — толщина. */
  size: Vec3;
  /** Поворот закрытой створки вокруг +Y, радианы. */
  yaw?: number;
  motion?: DoorMotion;
  /** Ход сдвига вдоль локальной оси +X, метры (motion: 'slide'). */
  slideDistance?: number;
  /** Угол распахивания вокруг петли, радианы (motion: 'swing'). */
  swingAngle?: number;
  /** Сторона петли для 'swing'. */
  hinge?: DoorHinge;
  /** Секунды полного хода закрыто -> открыто. */
  openSeconds?: number;
  /** Секунды полного хода открыто -> закрыто. По умолчанию равно openSeconds. */
  closeSeconds?: number;
  /** Автоматическое открывание/закрывание. Без него дверь управляется вручную. */
  autoCycle?: DoorAutoCycle;
  restitution?: number;
  friction?: number;
  color?: number;
  enabled?: boolean;
}

export interface ResolvedDoorConfig {
  id: string;
  position: Vec3;
  size: Vec3;
  yaw: number;
  motion: DoorMotion;
  slideDistance: number;
  swingAngle: number;
  hinge: DoorHinge;
  openSeconds: number;
  closeSeconds: number;
  autoCycle: DoorAutoCycle | null;
  restitution: number;
  friction: number;
  color: number;
  enabled: boolean;
}

export interface DoorTransform {
  position: Vec3;
  rotation: Quat;
}

/** Створка состоит в слое препятствий и сталкивается с шаром. */
export const DOOR_COLLISION_GROUPS = collisionGroups(CollisionLayers.OBSTACLE, CollisionLayers.BALL);

const MAX_STEP_SECONDS = 0.25;

function clamp01(value: number): number {
  if (!Number.isFinite(value) || value < 0) return 0;
  return value > 1 ? 1 : value;
}

export function quaternionFromYaw(yaw: number): Quat {
  const half = yaw / 2;
  return { x: 0, y: Math.sin(half), z: 0, w: Math.cos(half) };
}

function rotateAroundY(vector: Vec3, yaw: number): Vec3 {
  const sin = Math.sin(yaw);
  const cos = Math.cos(yaw);
  return { x: vector.x * cos + vector.z * sin, y: vector.y, z: -vector.x * sin + vector.z * cos };
}

export function resolveDoorConfig(config: DoorConfig): ResolvedDoorConfig {
  const size: Vec3 = { x: Math.abs(config.size.x), y: Math.abs(config.size.y), z: Math.abs(config.size.z) };
  const openSeconds = Math.max(0, config.openSeconds ?? 0.8);
  const cycle = config.autoCycle;
  return {
    id: config.id,
    position: { x: config.position.x, y: config.position.y, z: config.position.z },
    size,
    yaw: config.yaw ?? 0,
    motion: config.motion ?? 'slide',
    slideDistance: Math.abs(config.slideDistance ?? size.x),
    swingAngle: config.swingAngle ?? Math.PI / 2,
    hinge: config.hinge ?? 'left',
    openSeconds,
    closeSeconds: Math.max(0, config.closeSeconds ?? openSeconds),
    autoCycle: cycle
      ? {
          openHoldSeconds: Math.max(0, cycle.openHoldSeconds),
          closedHoldSeconds: Math.max(0, cycle.closedHoldSeconds),
          startOpen: cycle.startOpen ?? false,
        }
      : null,
    restitution: config.restitution ?? 0.35,
    friction: config.friction ?? 0.6,
    color: config.color ?? 0x9a6b3f,
    enabled: config.enabled ?? true,
  };
}

/** Положение и поворот створки для доли открытия progress из [0, 1]. */
export function doorPanelTransform(config: ResolvedDoorConfig, progress: number): DoorTransform {
  const t = clamp01(progress);
  if (config.motion === 'slide') {
    const offset = rotateAroundY({ x: config.slideDistance * t, y: 0, z: 0 }, config.yaw);
    return {
      position: {
        x: config.position.x + offset.x,
        y: config.position.y + offset.y,
        z: config.position.z + offset.z,
      },
      rotation: quaternionFromYaw(config.yaw),
    };
  }
  const halfWidth = config.size.x / 2;
  const hingeLocal: Vec3 = { x: config.hinge === 'left' ? -halfWidth : halfWidth, y: 0, z: 0 };
  const yaw = config.yaw + (config.hinge === 'left' ? 1 : -1) * config.swingAngle * t;
  const hingeWorld = rotateAroundY(hingeLocal, config.yaw);
  const centreFromHinge = rotateAroundY({ x: -hingeLocal.x, y: 0, z: 0 }, yaw);
  return {
    position: {
      x: config.position.x + hingeWorld.x + centreFromHinge.x,
      y: config.position.y + hingeWorld.y + centreFromHinge.y,
      z: config.position.z + hingeWorld.z + centreFromHinge.z,
    },
    rotation: quaternionFromYaw(yaw),
  };
}

export function doorPhase(progress: number, openTarget: boolean): DoorPhase {
  if (openTarget) return progress >= 1 ? 'open' : 'opening';
  return progress <= 0 ? 'closed' : 'closing';
}

export interface DoorDeps {
  body?: ObstacleBodyAdapter | null;
  view?: ObstacleViewAdapter | null;
}

/**
 * Дверь-препятствие: kinematic-створка, которая сдвигается или распахивается
 * и перекрывает проход, пока не открыта полностью.
 */
export class DoorObstacle implements ObstacleInstance {
  readonly id: string;
  readonly config: ResolvedDoorConfig;
  private readonly body: ObstacleBodyAdapter | null;
  private readonly view: ObstacleViewAdapter | null;
  private progress = 0;
  private openTarget = false;
  private holdRemaining = 0;
  private disposed = false;

  constructor(config: DoorConfig, deps: DoorDeps = {}) {
    this.config = resolveDoorConfig(config);
    this.id = this.config.id;
    this.body = deps.body ?? null;
    this.view = deps.view ?? null;
    const cycle = this.config.autoCycle;
    if (cycle) {
      this.openTarget = cycle.startOpen === true;
      this.progress = this.openTarget ? 1 : 0;
      this.holdRemaining = this.openTarget ? cycle.openHoldSeconds : cycle.closedHoldSeconds;
    }
    this.sync();
  }

  /** Доля открытия: 0 — закрыто, 1 — открыто полностью. */
  get openRatio(): number {
    return this.progress;
  }

  get phase(): DoorPhase {
    return doorPhase(this.progress, this.openTarget);
  }

  get isOpen(): boolean {
    return this.progress >= 1;
  }

  get isClosed(): boolean {
    return this.progress <= 0;
  }

  /** Створка перекрывает проход, пока не дошла до крайнего открытого положения. */
  get blocksPath(): boolean {
    return this.config.enabled && this.progress < 1;
  }

  get transform(): DoorTransform {
    return doorPanelTransform(this.config, this.progress);
  }

  open(): void {
    this.setOpen(true);
  }

  close(): void {
    this.setOpen(false);
  }

  toggle(): void {
    this.setOpen(!this.openTarget);
  }

  setOpen(open: boolean): void {
    if (this.disposed) return;
    this.openTarget = open;
    const cycle = this.config.autoCycle;
    this.holdRemaining = cycle ? (open ? cycle.openHoldSeconds : cycle.closedHoldSeconds) : 0;
  }

  /** Мгновенно выставить долю открытия без анимации (расстановка уровня, реплей). */
  setOpenRatio(ratio: number): void {
    if (this.disposed) return;
    this.progress = clamp01(ratio);
    this.openTarget = this.progress >= 1;
    this.sync();
  }

  setEnabled(enabled: boolean): void {
    if (this.disposed) return;
    this.config.enabled = enabled;
    this.body?.setEnabled?.(enabled);
  }

  update(deltaSeconds: number): void {
    if (this.disposed || !this.config.enabled) return;
    const dt = Math.min(Math.max(deltaSeconds, 0), MAX_STEP_SECONDS);
    if (dt <= 0 || !Number.isFinite(dt)) return;
    this.advanceAutoCycle(dt);
    const target = this.openTarget ? 1 : 0;
    if (this.progress === target) return;
    const duration = this.openTarget ? this.config.openSeconds : this.config.closeSeconds;
    const step = duration <= 0 ? 1 : dt / duration;
    this.progress = this.openTarget
      ? Math.min(1, this.progress + step)
      : Math.max(0, this.progress - step);
    this.sync();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.body?.dispose();
    this.view?.dispose();
  }

  private advanceAutoCycle(dt: number): void {
    const cycle = this.config.autoCycle;
    if (!cycle) return;
    const settled = this.openTarget ? this.progress >= 1 : this.progress <= 0;
    if (!settled) return;
    this.holdRemaining -= dt;
    if (this.holdRemaining > 0) return;
    this.openTarget = !this.openTarget;
    this.holdRemaining = this.openTarget ? cycle.openHoldSeconds : cycle.closedHoldSeconds;
  }

  private sync(): void {
    const { position, rotation } = doorPanelTransform(this.config, this.progress);
    this.body?.setTransform(position, rotation);
    this.view?.setTransform(position, rotation);
  }
}
