import RAPIER from '@dimforge/rapier3d-compat';
import * as THREE from 'three';
import type { Quat, Vec3 } from '../contracts/math';
import type { DoorConfig, ResolvedDoorConfig } from './Door';
import { DOOR_COLLISION_GROUPS, DoorObstacle, doorPanelTransform, resolveDoorConfig } from './Door';
import type { ObstacleBodyAdapter, ObstacleViewAdapter } from './ObstacleInstance';

/** Kinematic-створка в Rapier: тело перемещается состоянием двери, а не силами. */
export function createDoorBody(world: RAPIER.World, config: ResolvedDoorConfig): ObstacleBodyAdapter {
  const start = doorPanelTransform(config, 0);
  const body = world.createRigidBody(
    RAPIER.RigidBodyDesc.kinematicPositionBased()
      .setTranslation(start.position.x, start.position.y, start.position.z)
      .setRotation(start.rotation),
  );
  const collider = world.createCollider(
    RAPIER.ColliderDesc.cuboid(config.size.x / 2, config.size.y / 2, config.size.z / 2)
      .setRestitution(config.restitution)
      .setFriction(config.friction)
      .setCollisionGroups(DOOR_COLLISION_GROUPS),
    body,
  );
  collider.setEnabled(config.enabled);
  return {
    setTransform(position: Vec3, rotation: Quat): void {
      body.setNextKinematicTranslation(position);
      body.setNextKinematicRotation(rotation);
    },
    setEnabled(enabled: boolean): void {
      collider.setEnabled(enabled);
    },
    dispose(): void {
      world.removeRigidBody(body);
    },
  };
}

export class DoorView implements ObstacleViewAdapter {
  readonly mesh: THREE.Mesh;
  private readonly geometry: THREE.BoxGeometry;
  private readonly material: THREE.MeshStandardMaterial;

  constructor(config: ResolvedDoorConfig, parent?: THREE.Object3D) {
    this.geometry = new THREE.BoxGeometry(config.size.x, config.size.y, config.size.z);
    this.material = new THREE.MeshStandardMaterial({ color: config.color, roughness: 0.65, metalness: 0.1 });
    this.mesh = new THREE.Mesh(this.geometry, this.material);
    this.mesh.name = `door:${config.id}`;
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.mesh.visible = config.enabled;
    parent?.add(this.mesh);
  }

  setTransform(position: Vec3, rotation: Quat): void {
    this.mesh.position.set(position.x, position.y, position.z);
    this.mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
  }

  dispose(): void {
    this.mesh.removeFromParent();
    this.geometry.dispose();
    this.material.dispose();
  }
}

export interface CreateDoorOptions {
  world?: RAPIER.World;
  parent?: THREE.Object3D;
}

/** Собрать дверь с реальным коллайдером и мешем; каждая часть подключается по наличию. */
export function createDoor(config: DoorConfig, options: CreateDoorOptions = {}): DoorObstacle {
  const resolved = resolveDoorConfig(config);
  const body = options.world ? createDoorBody(options.world, resolved) : null;
  const view = options.parent ? new DoorView(resolved, options.parent) : null;
  return new DoorObstacle(config, { body, view });
}
